254		if rec.Code != http.StatusAccepted || payload["replayed"] != 1 {
255			t.Fatalf("replay of oldest: status = %d payload = %v", rec.Code, payload)
256		}
257	
258		// One more id pushes the oldest out despite the replay.
259		post(10000, 1)
260	
261		page := decodeLogPage(t, getLogs(t, h, "q=msg-0"))
262		if len(page.Entries) != 0 {
263			t.Fatalf("oldest id not evicted: %v", pageIDs(page))
264		}
265		page = decodeLogPage(t, getLogs(t, h, "q=msg-10000"))
266		if len(page.Entries) != 1 {
267			t.Fatalf("newest id missing: %v", pageIDs(page))
268		}
269	
270		// An evicted id can be written again as a fresh entry.
271		rec = postLogEntries(t, h, []string{oldest})
272		_ = decodeJSON(rec, &payload)
273		if rec.Code != http.StatusAccepted || payload["accepted"] != 1 {
274			t.Fatalf("rewrite of evicted id: status = %d payload = %v", rec.Code, payload)
275		}
276	}
