440		page := decodeLogPage(t, getLogs(t, h, "limit=2"))
441		if page.NextCursor == nil {
442			t.Fatal("expected a cursor")
443		}
444		cursor := *page.NextCursor
445	
446		// A follow-up may only carry the cursor.
447		rec := getLogs(t, h, "cursor="+cursor+"&limit=2")
448		if rec.Code != http.StatusBadRequest || errorCode(t, rec) != "invalid_log_query" {
449			t.Fatalf("cursor+limit: status = %d code = %q", rec.Code, errorCode(t, rec))
450		}
451	
452		// Garbage cursors are rejected.
453		for _, bad := range []string{"not-a-cursor", "AAAA.BBBB", cursor + "x", cursor[:len(cursor)-2] + "zz"} {
454			rec := getLogs(t, h, "cursor="+bad)
