463			t.Fatalf("cross-tenant cursor: status = %d code = %q", rec.Code, errorCode(t, rec))
464		}
465	
466		// New writes after the first page never mix into later pages.
467		if rec := postLogEntries(t, h, []string{
468			makeLogEntry("late", "2026-01-02T03:04:09Z", "info", "cur"),
469		}); rec.Code != http.StatusAccepted {
