115		}
116		// Identical content, including the same instant expressed in another zone.
117		replay := makeSpan(sampleTraceID, "0000000000000001", "", "web", "root",
118			"2026-01-02T11:04:05+08:00", "2026-01-02T11:04:06+08:00", "ok", `{"route":"/a"}`)
119		rec := postSpanBatch(t, h, []string{replay})
120		if rec.Code != http.StatusAccepted {
121			t.Fatalf("replay: status = %d, want 202", rec.Code)
122		}
123		var payload map[string]int
124		if err := decodeJSON(rec, &payload); err != nil {
125			t.Fatalf("decode: %v", err)
126		}
127		if payload["accepted"] != 0 || payload["replayed"] != 1 {
128			t.Fatalf("payload = %v, want accepted=0 replayed=1", payload)
129		}
130	
131		// An identical duplicate inside one batch is a replay, not a conflict.
132		rec = postSpanBatch(t, h, []string{replay, sp})
133		if rec.Code != http.StatusAccepted {
134			t.Fatalf("in-batch replay: status = %d, want 202", rec.Code)
135		}
136		if err := decodeJSON(rec, &payload); err != nil {
137			t.Fatalf("decode: %v", err)
138		}
139		if payload["accepted"] != 0 || payload["replayed"] != 2 {
140			t.Fatalf("payload = %v, want accepted=0 replayed=2", payload)
141		}
142	}
