151			"2026-01-02T03:04:05Z", "2026-01-02T03:04:07Z", "ok", `{"route":"/a"}`)
152		rec := postSpanBatch(t, h, []string{changed})
153		if rec.Code != http.StatusConflict || errorCode(t, rec) != "span_conflict" {
154			t.Fatalf("conflict: status = %d code = %q", rec.Code, errorCode(t, rec))
155		}
156	
157		// A conflict in the second span must not commit the first (new) span.
158		other := makeSpan(sampleTraceID, "0000000000000009", "", "web", "other",
159			"2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `{}`)
