165		d := decodeTrace(t, rec)
166		if len(d.Spans) != 1 {
167			t.Fatalf("conflict mutated state: spans = %d, want 1", len(d.Spans))
168		}
169		if d.Spans[0].EndTime != "2026-01-02T03:04:06Z" {
170			t.Fatalf("stored end_time = %q, want unchanged", d.Spans[0].EndTime)
171		}
172	
173		// Two different payloads for one (trace_id, span_id) inside a batch also
174		// conflict and leave state untouched.
175		a := makeSpan("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "0000000000000007", "", "web", "a",
176			"2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `{}`)
177		b := makeSpan("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "0000000000000007", "", "web", "b",
178			"2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `{}`)
179		if rec := postSpanBatch(t, h, []string{a, b}); rec.Code != http.StatusConflict {
180			t.Fatalf("in-batch conflict: status = %d, want 409", rec.Code)
181		}
182		if rec := getTrace(t, h, tracesPrefix+"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"); rec.Code != http.StatusNotFound {
183			t.Fatalf("in-batch conflict mutated state: status = %d, want 404", rec.Code)
184		}
185	}
