	} `json:"logs"`
}

func decodeTrace(t *testing.T, rec *httptest.ResponseRecorder) traceDetail {
	t.Helper()
	var d traceDetail
	if err := decodeJSON(rec, &d); err != nil {
		t.Fatalf("decode trace: %v", err)
	}
	return d
}

