178		if rec := tenantJSON(t, h, http.MethodPut, silencesPrefix+"sil1", silBody, "team-a"); rec.Code != http.StatusCreated {
179			t.Fatalf("team-a silence put: %d %s", rec.Code, rec.Body.String())
180		}
