182		if rec := tenantJSON(t, h, http.MethodPut, notificationRoutesPrefix+"rt1", routeBody, "team-a"); rec.Code != http.StatusCreated {
183			t.Fatalf("team-a route put: %d %s", rec.Code, rec.Body.String())
184		}
185		// Inhibit rule in default references a rule id that only exists in team-a;
186		// it must never resolve across tenants.
187		inhBody := `{"source_rule_ids":["ghost"],"target_rule_ids":["shared_r"],"comment":""}`
188		if rec := tenantJSON(t, h, http.MethodPut, inhibitRulesPrefix+"inh1", inhBody, "default"); rec.Code != http.StatusCreated {
189			t.Fatalf("default inhibit put: %d %s", rec.Code, rec.Body.String())
190		}
191	
192		defaultAlerts := tenantJSON(t, h, http.MethodGet, alertsPath, "")
193		if state := alertStateFor(defaultAlerts, "shared_r"); state != "firing" {
194			t.Fatalf("default shared_r state = %q, want firing (silence/inhibition leaked across tenants)", state)
195		}
196		teamAAlerts := tenantJSON(t, h, http.MethodGet, alertsPath, "", "team-a")
197		if state := alertStateFor(teamAAlerts, "shared_r"); state != "no_data" {
198			t.Fatalf("team-a shared_r state = %q, want no_data (metrics leaked across tenants)", state)
199		}
200	
201		pd := decodeBody(t, tenantJSON(t, h, http.MethodGet, notificationPlanPath, ""))
202		if deliv, _ := pd["deliveries"].([]any); len(deliv) != 0 {
203			t.Fatalf("default must have no route for shared_r, got %v", pd["deliveries"])
204		}
205		if unrouted, _ := pd["unrouted_alert_ids"].([]any); len(unrouted) != 1 || unrouted[0] != "shared_r" {
206			t.Fatalf("default shared_r must be unrouted, got %v", pd["unrouted_alert_ids"])
207		}
208		pa := decodeBody(t, tenantJSON(t, h, http.MethodGet, notificationPlanPath, "", "team-a"))
209		if deliv, _ := pa["deliveries"].([]any); len(deliv) != 0 {
210			t.Fatalf("team-a must have no deliveries (no firing alert), got %v", pa["deliveries"])
211		}
212	
213		// Collection endpoints never surface another tenant's resources.
214		for _, tc := range []struct {
215			target string
216			key    string
217		}{
218			{silencesPath, "silences"},
219			{inhibitRulesPath, "rules"},
220			{notificationRoutesPath, "routes"},
221		} {
222			rec := tenantJSON(t, h, http.MethodGet, tc.target, "", "team-a")
223			body := decodeBody(t, rec)
224			if tc.target == inhibitRulesPath {
