232		if list, _ := inhDefault["rules"].([]any); len(list) != 1 {
233			t.Fatalf("default should keep its own inhibit rule, got %v", inhDefault["rules"])
234		}
235	
236		// Deleting in team-a must not touch default's rule.
237		if rec := tenantJSON(t, h, http.MethodDelete, alertRulesPrefix+"shared_r", "", "team-a"); rec.Code != http.StatusNoContent {
238			t.Fatalf("team-a delete: %d", rec.Code)
239		}
240		if rec := tenantJSON(t, h, http.MethodGet, alertRulesPrefix+"shared_r", "", "team-a"); rec.Code != http.StatusNotFound {
241			t.Fatalf("team-a get after delete: got %d want 404", rec.Code)
242		}
243		if rec := tenantJSON(t, h, http.MethodGet, alertRulesPrefix+"shared_r", "", "default"); rec.Code != http.StatusOK {
244			t.Fatalf("default rule must survive team-a delete, got %d", rec.Code)
