422	func TestDifferentTenantsDoNotBlockEachOther(t *testing.T) {
423		registry := newTenantRegistry()
424		h := newHandler(registry)
425	
426		// Hold tenant block-a's own store lock for the whole test; a request to
427		// block-b must still complete because each tenant has an independent lock.
428		storeA := registry.storeFor("block-a")
429		storeA.mu.Lock()
430		defer storeA.mu.Unlock()
431	
432		done := make(chan int, 1)
433		go func() {
434			rec := httptest.NewRecorder()
435			req := httptest.NewRequest(http.MethodGet, alertRulesPath, nil)
