476				t.Fatalf("tenant %s: want exactly its own one series, got %d: %s", tenant, n, rec.Body.String())
477			}
478			rec = doRequest(t, h, http.MethodGet, metricsPath+"?name=hits&label.w="+strconv.Itoa(w), "", "", tenant)
479			if v := metricValue(t, rec); v != float64(25*(w+1)) {
480				t.Fatalf("tenant %s: value = %v, want %d (cross-tenant write observed)", tenant, v, 25*(w+1))
481			}
