	}
	if len(s.logOrder) > maxLogIDsPerTenant {
		excess := len(s.logOrder) - maxLogIDsPerTenant
		for _, id := range s.logOrder[:excess] {
			delete(s.logs, id)
		}
		s.logOrder = append([]string(nil), s.logOrder[excess:]...)
	}
	return accepted, replayed, sampledOut, true
}

