func TestSamplingPolicyInvalidBodies(t *testing.T) {
	h := Handler()
	cases := map[string]string{
		"not json":       `{`,
		"trailing data":  `{"log_rate":1,"trace_rate":1} x`,
		"not object":     `[1,1]`,
		"null":           `null`,
